tests.harness:
class Producto:
    precio = Positivo()
    def __init__(self, precio):
        self.precio = precio
p = Producto(10)
assert p.precio == 10
err = False
try:
    Producto(-5)
except ValueError:
    err = True
assert err is True

class Config:
    version = SoloLectura(3)
c = Config()
assert c.version == 3
err = False
try:
    c.version = 9
except AttributeError:
    err = True
assert err is True
